V1001_BLOCK_START_ACTION = v1001.PlayerBlockActionData(
    player_action_type=v1001.PlayerActionType.START_DESTROY_BLOCK, pos=v1001.BlockPos(x=21, y=22, z=23), facing=4
)

GOLDENS = [
    pytest.param(
        v1001.PlayerAuthInputPacket(**BODY, input_data=1 << V1001_FLAG.ASCEND),
        V1001_PLAIN,
        id="v1001-plain",
    ),
    pytest.param(
        v1001.PlayerAuthInputPacket(
            **BODY,
            input_data=1 << V1001_FLAG.ASCEND
            | 1 << V1001_FLAG.PERFORM_BLOCK_ACTIONS
            | 1 << V1001_FLAG.PERFORM_ITEM_STACK_REQUEST
            | 1 << V1001_FLAG.IS_IN_CLIENT_PREDICTED_VEHICLE
            | 1 << V1001_FLAG.SNEAK_CURRENT_RAW,
            item_stack_request=v1001.ItemStackRequestData(client_request_id=v1001.ItemStackRequestId(raw_id=-2)),
            player_block_actions=[V1001_BLOCK_START_ACTION],
            vehicle_rot=v1001.Vec2(x=24.0, y=25.0),
            client_predicted_vehicle=26,
        ),
        V1001_ARMS,
        id="v1001-every-modelled-arm",
    ),
    pytest.param(
        v1001.PlayerAuthInputPacket(
            **BODY,
            input_data=1 << V1001_FLAG.ASCEND | 1 << V1001_FLAG.PERFORM_ITEM_INTERACTION,
            item_use_transaction=v1001.PackedItemUseLegacyInventoryTransaction(
                id=-4, slots=V1001_LEGACY_SLOTS, transaction=V1001_ITEM_TRANSACTION
            ),
        ),
        V1001_ITEM_INTERACTION,
        id="v1001-item-interaction",
    ),
    pytest.param(
        v1001.PlayerAuthInputPacket(
            **BODY,
            input_data=1 << V1001_FLAG.PERFORM_ITEM_INTERACTION,
            item_use_transaction=v1001.PackedItemUseLegacyInventoryTransaction(
                id=-3, slots=[], transaction=V1001_ITEM_TRANSACTION
            ),
        ),
        V1001_ODD_REQUEST_ID,
        id="v1001-odd-request-id",
    ),
    pytest.param(
        v1001.PlayerAuthInputPacket(**BODY, input_data=1 << V1001_FLAG.ASCEND | 1 << V1001_FLAG.SNEAK_CURRENT_RAW),
        V1001_VEHICLE_ARM_UNTAKEN,
        id="v1001-vehicle-arm-untaken",
    ),
    pytest.param(
        v1001.PlayerAuthInputPacket(
            **BODY,
            input_data=1 << V1001_FLAG.ASCEND
            | 1 << V1001_FLAG.SNEAK_CURRENT_RAW
            | 1 << V1001_FLAG.IS_IN_CLIENT_PREDICTED_VEHICLE,
            vehicle_rot=v1001.Vec2(x=24.0, y=25.0),
            client_predicted_vehicle=26,
        ),
        V1001_VEHICLE_ARM_TAKEN,
        id="v1001-vehicle-arm-taken",
    ),
    pytest.param(
        v2168.PlayerAuthInputPacket(**BODY, input_data=[V2168_FLAG.ASCEND]),
        V2168_PLAIN,
        id="v2168-every-optional-absent",
    ),
    pytest.param(
        v2168.PlayerAuthInputPacket(
            **BODY,
            input_data=[
                V2168_FLAG.ASCEND,
                V2168_FLAG.PERFORM_BLOCK_ACTIONS,
                V2168_FLAG.IS_IN_CLIENT_PREDICTED_VEHICLE,
                V2168_FLAG.SNEAK_CURRENT_RAW,
            ],
            player_block_actions=[
                v2168.PlayerBlockActionData(
                    player_action_type=v2168.PlayerActionType.START_DESTROY_BLOCK,
                    pos=v2168.BlockPos(x=21, y=22, z=23),
                    facing=4,
                )
            ],
            vehicle_rot=v2168.Vec2(x=24.0, y=25.0),
            client_predicted_vehicle=26,
        ),
        V2168_BLOCK_ACTIONS_AND_VEHICLE,
        id="v2168-block-actions-and-vehicle",
    ),
    pytest.param(
        v2168.PlayerAuthInputPacket(**BODY, input_data=[V2168_FLAG.ASCEND], vehicle_rot=v2168.Vec2(x=24.0, y=25.0)),
        V2168_VEHICLE_ROTATION,
        id="v2168-vehicle-rotation-only",
    ),
]

BLOCK_ACTION_GOLDENS = [
    pytest.param(V1001_BLOCK_START_ACTION, V1001_BLOCK_START, id="v1001-start"),
    pytest.param(
        v1001.PlayerBlockActionData(player_action_type=v1001.PlayerActionType.STOP_DESTROY_BLOCK),
        V1001_BLOCK_STOP,
        id="v1001-stop",
    ),
    pytest.param(
        v2168.PlayerBlockActionData(player_action_type=v2168.PlayerActionType.STOP_DESTROY_BLOCK),
        V2168_BLOCK_STOP,
        id="v2168-stop",
    ),
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_player_auth_input_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_player_auth_input_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


@pytest.mark.parametrize(("action", "golden"), BLOCK_ACTION_GOLDENS)
def test_player_block_action_encodes_to_its_golden(action, golden):
    assert bytes(action) == golden


@pytest.mark.parametrize(("action", "golden"), BLOCK_ACTION_GOLDENS)
def test_player_block_action_decodes_from_its_golden(action, golden):
    assert type(action).from_bytes(golden) == action


def test_v1001_leaves_the_legacy_slots_off_the_wire_for_an_odd_request_id():
    packet = v1001.PlayerAuthInputPacket(
        **BODY,
        input_data=1 << V1001_FLAG.PERFORM_ITEM_INTERACTION,
        item_use_transaction=v1001.PackedItemUseLegacyInventoryTransaction(
            id=-3, slots=V1001_LEGACY_SLOTS, transaction=V1001_ITEM_TRANSACTION
        ),
    )
    assert bytes(packet) == V1001_ODD_REQUEST_ID


def test_v1001_writes_no_bytes_for_a_vehicle_arm_the_flags_do_not_take():
    packet = v1001.PlayerAuthInputPacket(
        **BODY,
        input_data=1 << V1001_FLAG.ASCEND | 1 << V1001_FLAG.SNEAK_CURRENT_RAW,
        vehicle_rot=v1001.Vec2(x=24.0, y=25.0),
        client_predicted_vehicle=26,
    )
    assert bytes(packet) == V1001_VEHICLE_ARM_UNTAKEN


def test_v2168_rejects_a_v1001_body():
    with pytest.raises(ValueError, match="at byte"):
        v2168.PlayerAuthInputPacket.from_bytes(V1001_PLAIN)


def test_v1001_rejects_a_v2168_body_as_trailing_bytes():
    with pytest.raises(ValueError, match="trailing bytes"):
        v1001.PlayerAuthInputPacket.from_bytes(V2168_PLAIN)


def test_v1001_leaves_the_block_action_position_off_the_wire_for_a_stop():
    action = v1001.PlayerBlockActionData(
        player_action_type=v1001.PlayerActionType.STOP_DESTROY_BLOCK, pos=v1001.BlockPos(x=21, y=22, z=23), facing=4
    )
    assert bytes(action) == V1001_BLOCK_STOP


def test_v2168_rejects_a_block_action_without_its_position():
    with pytest.raises(ValueError, match="at byte"):
        v2168.PlayerBlockActionData.from_bytes(bytes.fromhex("04"))


def test_2168_appends_internal_update_to_the_input_flags():
    assert V2168_FLAG.INTERNAL_UPDATE == 65


def test_v1001_input_data_holds_its_last_flag():
    packet = v1001.PlayerAuthInputPacket(**BODY, input_data=1 << 64)
    assert v1001.PlayerAuthInputPacket.from_bytes(bytes(packet)) == packet


def test_v1001_input_data_refuses_a_flag_past_its_width():
    with pytest.raises(TypeError, match="incompatible function arguments"):
        v1001.PlayerAuthInputPacket(**BODY, input_data=1 << 65)
